POST /v1/api/payment-link

 Body shape (from the OpenAPI example):
  {
    "nickname": "Premium Widget Payment",
    "amount_type": "FIXED",
    "products": [
      {
        "id": "prod_abc123",
        "product_prices": [
          { "id": "price_abc123", "quantity": 1, "adjustable": false }
        ]
      }
    ],
    "allowed_payment_methods": ["PAYMENT_CARD"],
    "collect_buyer_details": "email",
    "additional_details": {
      "terms_of_service_url": "https://example.com/terms"
    }
  }

  Response (201):
  {
    "success": true,
    "data": {
      "id": "pl_abc123",
      "url": "https://pay.example.com/pl_abc123",
      "amount_cents": 5000,
      "currency": "USD",
      "status": "ACTIVE",
      "created_at": "..."
    }
  }

