1	'use client';
2	
3	import { AuthAtoms } from '@modules/auth/jotai/atoms';
4	import { Button } from '@modules/shared/button';
5	import { Label } from '@modules/shared/label';
6	import { formatPrice } from '@modules/shared/utils/formatPrice';
7	import { Routes } from 'const/Routes';
8	import { useAtomValue } from 'jotai';
9	import { createPendingInvestmentTransaction } from 'lib/firebase/transaction-actions';
10	import { cn } from 'lib/utils';
11	import { ChevronLeft } from 'lucide-react';
12	import Link from 'next/link';
13	import { FC, FormEvent, useMemo, useState } from 'react';
14	import { toast } from 'sonner';
15	
16	const PRESET_AMOUNTS = [5000, 10000, 25000, 50000, 100000, 250000];
17	
18	const snapToMinimum = (value: number, min: number): number =>
19	  value < min ? min : value;
20	
21	export const InvestFlow: FC<{
22	  project: Project;
23	  suggestedAmount?: number;
24	}> = ({ project, suggestedAmount }) => {
25	  const firestoreUser = useAtomValue(AuthAtoms.user);
26	  const minInvestment = project.financials.minInvestment ?? 0;
27	
28	  const initialAmount = useMemo(() => {
29	    if (suggestedAmount) return snapToMinimum(suggestedAmount, minInvestment);
30	    return minInvestment;
31	  }, [suggestedAmount, minInvestment]);
32	
33	  const [amount, setAmount] = useState<number>(initialAmount);
34	  const [loading, setLoading] = useState(false);
35	  const [checkoutUrl, setCheckoutUrl] = useState<string | null>(null);
36	
37	  const invalid = amount < minInvestment;
38	
39	  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
40	    event.preventDefault();
41	    if (loading) return;
42	
43	    if (!firestoreUser) {
44	      toast.error('You must be logged in to invest.');
45	      return;
46	    }
47	    if (invalid) {
48	      toast.error(`Minimum investment is ${formatPrice(minInvestment)}.`);
49	      return;
50	    }
51	
52	    setLoading(true);
53	    try {
54	      const res = await fetch('/api/embedded-checkout', {
55	        method: 'POST',
56	        headers: { 'Content-Type': 'application/json' },
57	        body: JSON.stringify({ projectId: project.id, amount }),
58	      });
59	
60	      const data = (await res.json()) as
61	        | CreateEmbeddedCheckoutResponse
62	        | CreateEmbeddedCheckoutErrorResponse;
63	
64	      if (!res.ok || !('success' in data)) {
65	        const message =
66	          'error' in data && data.error?.message
67	            ? data.error.message
68	            : 'Could not start checkout. Please try again.';
69	        toast.error(message);
70	        return;
71	      }
72	
73	      try {
74	        await createPendingInvestmentTransaction({
75	          projectId: project.id,
76	          projectName: project.name,
77	          projectType: project.type,
78	          amount,
79	          userId: firestoreUser.uid,
80	          userEmail: firestoreUser.email || '',
81	          checkoutSessionId: data.data.id,
82	        });
83	      } catch (recordError) {
