import { z } from 'zod';

/**
 * Internal helpers shared by `http-client.ts` (browser) and `http-server.ts`.
 * Do not import from this file directly in feature services — use `http` or
 * `httpServer` instead.
 *
 * The `HttpMethod` and `RequestOptions` types are declared globally in
 * `types/http-service.d.ts` — no import needed.
 */

/**
 * Error envelope returned by the API:
 *   { success: false, timestamp, error: { code, message, details? } }
 */
export const ErrorEnvelopeSchema = z.object({
  success: z.literal(false),
  timestamp: z.string(),
  error: z.object({
    code: z.string(),
    message: z.string(),
    details: z.unknown().optional(),
  }),
});
export type ErrorEnvelope = z.infer<typeof ErrorEnvelopeSchema>;

export class ApiError extends Error {
  /** API error code (from the envelope) when available. */
  public readonly code?: string;
  /** API error details payload when available. */
  public readonly details?: unknown;
  /** API-reported timestamp when available. */
  public readonly timestamp?: string;
  /** Raw parsed body (JSON object, string, or null). Always present. */
  public readonly payload: unknown;

  constructor(
    public readonly status: number,
    public readonly statusText: string,
    payload: unknown,
    message?: string,
  ) {
    const parsed = ErrorEnvelopeSchema.safeParse(payload);
    const envelope = parsed.success ? parsed.data : null;

    super(
      message ??
        envelope?.error.message ??
        `API ${status} ${statusText || 'error'}`,
    );
    this.name = 'ApiError';
    this.payload = payload;
    if (envelope) {
      this.code = envelope.error.code;
      this.details = envelope.error.details;
      this.timestamp = envelope.timestamp;
    }
  }
}

/**
 * Wraps a schema in the standard success envelope:
 *   { success: true, timestamp, data: <T> }
 *
 * Use on every service method so you get the inner `data` back directly:
 *
 *   const project = (await http.get(envelope(ProjectSchema), { ... })).data;
 *
 * If an endpoint returns a bare payload (no envelope), skip this helper.
 */
export const envelope = <TSchema extends z.ZodTypeAny>(data: TSchema) =>
  z.object({
    success: z.literal(true),
    timestamp: z.string(),
    data,
  });

export const buildUrl = (
  baseUrl: string,
  path: string,
  query?: RequestOptions['query'],
): string => {
  if (!path.startsWith('/')) {
    throw new Error(`Service path must start with "/": ${path}`);
  }
  const url = new URL(`${baseUrl}${path}`);
  if (query) {
    for (const [key, value] of Object.entries(query)) {
      if (value === undefined || value === null) continue;
      url.searchParams.set(key, String(value));
    }
  }
  return url.toString();
};

const safeJsonParse = (text: string): unknown => {
  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
};

export const parseResponse = async (response: Response): Promise<unknown> => {
  const text = await response.text();
  const payload = text ? safeJsonParse(text) : null;

  if (!response.ok) {
    throw new ApiError(response.status, response.statusText, payload);
  }

  return payload;
};

export const isWriteMethod = (method: HttpMethod): boolean =>
  method === 'POST' || method === 'PUT' || method === 'PATCH';

